from collections import defaultdict

class Solution:
    def largestValsFromLabels(self, values: list[int], labels: list[int], numWanted: int, useLimit: int) -> int:
        items = sorted(zip(values, labels), key=lambda x: -x[0])
        label_counts = defaultdict(int)
        total = 0
        taken = 0
        for v, l in items:
            if label_counts[l] < useLimit:
                total += v
                label_counts[l] += 1
                taken += 1
                if taken == numWanted:
                    break
        return total

class Solution {
public:
    int largestValsFromLabels(vector<int>& values, vector<int>& labels, int numWanted, int useLimit) {
        int n = values.size();
        vector<pair<int, int>> items(n);
        for (int i = 0; i < n; ++i) items[i] = {values[i], labels[i]};
        sort(items.begin(), items.end(), [](const pair<int, int>& a, const pair<int, int>& b) {
            return a.first > b.first;
        });

        unordered_map<int, int> label_counts;
        int total = 0, taken = 0;
        for (const auto& item : items) {
            if (label_counts[item.second] < useLimit) {
                total += item.first;
                label_counts[item.second]++;
                taken++;
                if (taken == numWanted) break;
            }
        }
        return total;
    }
};

class Solution {
    public int largestValsFromLabels(int[] values, int[] labels, int numWanted, int useLimit) {
        int n = values.length;
        int[][] items = new int[n][2];
        for (int i = 0; i < n; ++i) {
            items[i][0] = values[i];
            items[i][1] = labels[i];
        }
        Arrays.sort(items, (a, b) -> Integer.compare(b[0], a[0]));

        Map<Integer, Integer> labelCounts = new HashMap<>();
        int total = 0, taken = 0;
        for (int[] item : items) {
            int count = labelCounts.getOrDefault(item[1], 0);
            if (count < useLimit) {
                total += item[0];
                labelCounts.put(item[1], count + 1);
                taken++;
                if (taken == numWanted) break;
            }
        }
        return total;
    }
}

var largestValsFromLabels = function(values, labels, numWanted, useLimit) {
    const n = values.length;
    const items = [];
    for (let i = 0; i < n; i++) {
        items.push([values[i], labels[i]]);
    }
    items.sort((a, b) => b[0] - a[0]);

    const labelCounts = new Map();
    let total = 0, taken = 0;
    for (const [v, l] of items) {
        const c = labelCounts.get(l) || 0;
        if (c < useLimit) {
            total += v;
            labelCounts.set(l, c + 1);
            taken++;
            if (taken === numWanted) break;
        }
    }
    return total;
};
